INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (0, 'h1', 'Week 45', '2026-11-02', '2026-11-08', '2026-11-01', 'headline', '', '', 'The Fed held, tech broke on Friday and crypto fell with the reported Binance hack. All four markets sit below their mid or below their range, with nothing open under your rules: wait for a reclaim of the mid or a test of the range low.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (1, 'x1', 'Week 45', '2026-11-02', '2026-11-08', '2026-11-01', 'exit', 'NDX', 'NQ', 'Exit rule hit 30 Oct', '', '', '', '', '', 'Two closes below the EMA50 in Uptrend weak, the dangerous state in your test: 28% chance of a 12% drop within 60 days.');
